-- V37__seed_upgrade_tests.sql
-- Seed 30 Upgrade Tests (10 per Level) & 900 Rich TOEIC Questions Bank

SET @toeic_exam_id = (SELECT id FROM exam_types WHERE code = 'TOEIC' LIMIT 1);
SET @admin_user_id = (SELECT id FROM users WHERE username = 'admin' LIMIT 1);

-- ========================================================
-- UPGRADE TESTS FOR TOEIC Dưới 500 (Target Level: TOEIC_INTERMEDIATE)
-- ========================================================


INSERT INTO quizzes (quiz_code, title, description, quiz_type, quiz_category, time_limit_seconds, pass_score, max_attempts, shuffle_questions, shuffle_options, total_questions, is_active, exam_type_id, level_id, created_by, updated_by, created_at, updated_at)
SELECT 'UPGRADE-U500-01', 'Upgrade Test Dưới 500 - #01', 'Bài kiểm tra nâng cấp trình độ TOEIC Dưới 500 - Đề số #01. Đạt từ 80% (24/30 câu) để nâng cấp trình độ ngay lập tức.', 'MIXED', 'LEVEL_UP', 1800, 80.00, 999, 1, 1, 30, 1, @toeic_exam_id, 2, @admin_user_id, @admin_user_id, NOW(), NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM quizzes WHERE quiz_code = 'UPGRADE-U500-01');


INSERT INTO quiz_questions (quiz_id, question_text, question_type, explanation, points, display_order, is_active, created_at, updated_at)
SELECT id, '[Q1] Vocabulary: Select the best word to complete: The company plans to warranty period its guarantee in the upcoming fiscal quarter.', 'MULTIPLE_CHOICE', 'Từ ''warranty period'' phù hợp ngữ cảnh câu trong chủ đề Warranties & Quality.', 1, 1, 1, NOW(), NOW()
FROM quizzes WHERE quiz_code = 'UPGRADE-U500-01'
AND NOT EXISTS (SELECT 1 FROM quiz_questions WHERE quiz_id = (SELECT id FROM quizzes WHERE quiz_code = 'UPGRADE-U500-01') AND display_order = 1);


